filter_description:
Şu an etiket, oluşturulma zamanı ve koleksiyon ID'sine göre filtreleme desteklenir. Aşağıdaki biçimde doldurulmalı:
{
  "tags": {
    "$and": ["Etiket 1","Etiket 2"],
    "$or": ["$and etiketi varsa and geçerli olur, or geçerli olmaz"]
  },
  "createTime": {
      "$gte": "YYYY-MM-DD HH:mm biçimi yeterli, koleksiyonun oluşturulma zamanı bu zamandan sonra",
      "$lte": "YYYY-MM-DD HH:mm biçimi yeterli, koleksiyonun oluşturulma zamanı bu zamandan önce, $gte ile birlikte kullanılabilir"
  },
  "collectionIds": ["Koleksiyon ID1", "Koleksiyon ID2", "Klasör ID'si desteklenir, tüm alt koleksiyonlar otomatik genişletilerek alınır"]
}

